WITH _hq_raw AS (SELECT tuple(analytics.orders.created_at, analytics.orders.amount_cents, NULL) AS _hq_row FROM analytics.orders WHERE analytics.orders.tenant_id = ?),
_hq_source AS (SELECT toDateTime64(assumeNotNull(tupleElement(_hq_row, 1)), 9, 'America/New_York') AS _hq_time, tupleElement(_hq_row, 2) AS _hq_v0, tupleElement(_hq_row, 3) AS _hq_a0 FROM _hq_raw WHERE isNotNull(tupleElement(_hq_row, 1))),
_hq_bounds AS (SELECT parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_lower, parseDateTime64BestEffort(?, 9, timezoneOf(assumeNotNull((SELECT _hq_time FROM _hq_source LIMIT 0)))) AS _hq_upper, toStartOfHour(_hq_lower) AS _hq_first, toStartOfHour(_hq_upper) AS _hq_last),
_hq_series AS (SELECT addHours(_hq_first, arrayJoin(range(toUInt64(dateDiff('hour', _hq_first, _hq_last) + 1 + 0 + throwIf(position(toTypeName(tupleElement((SELECT _hq_row FROM _hq_raw LIMIT 0), 1)), 'Date') > 0 AND position(toTypeName(tupleElement((SELECT _hq_row FROM _hq_raw LIMIT 0), 1)), 'DateTime') = 0, 'Sub-day time measures require a time-of-day column; Date and Date32 are not supported.') + 0 + 0 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.'))))) AS _hq_period FROM _hq_bounds),
_hq_shift_ranges0 AS (SELECT _hq_period, subtractHours(greatest(_hq_period, _hq_lower), 1) AS _hq_shift_lower, subtractHours(least(addHours(_hq_period, 1), _hq_upper), 1) AS _hq_shift_upper, (_hq_period > _hq_lower OR 1) AS _hq_shift_lower_inclusive, (_hq_upper < addHours(_hq_period, 1) AND 1) AS _hq_shift_upper_inclusive FROM _hq_series CROSS JOIN _hq_bounds),
_hq_shift_keys0 AS (SELECT *, addHours(toStartOfHour(_hq_shift_lower), arrayJoin(range(toUInt64(greatest(0, dateDiff('hour', toStartOfHour(_hq_shift_lower), toStartOfHour(_hq_shift_upper)) + if(_hq_shift_upper > toStartOfHour(_hq_shift_upper) OR _hq_shift_upper_inclusive, 1, 0)))))) AS _hq_source_period FROM _hq_shift_ranges0),
_hq_shift_ranges1 AS (SELECT _hq_period, addDays(subtractMonths(greatest(_hq_period, _hq_lower), 1), dateDiff('day', subtractMonths(greatest(_hq_period, _hq_lower), 1), subtractMonths(_hq_period, 1)) + dateDiff('day', _hq_period, greatest(_hq_period, _hq_lower))) AS _hq_shift_lower, if(_hq_upper >= addHours(_hq_period, 1), addHours(subtractMonths(_hq_period, 1), 1), addDays(subtractMonths(least(addHours(_hq_period, 1), _hq_upper), 1), dateDiff('day', subtractMonths(least(addHours(_hq_period, 1), _hq_upper), 1), subtractMonths(_hq_period, 1)) + dateDiff('day', _hq_period, least(addHours(_hq_period, 1), _hq_upper)))) AS _hq_shift_upper, (_hq_period > _hq_lower OR 1) AS _hq_shift_lower_inclusive, (_hq_upper < addHours(_hq_period, 1) AND 1) AS _hq_shift_upper_inclusive FROM _hq_series CROSS JOIN _hq_bounds),
_hq_shift_keys1 AS (SELECT *, addHours(toStartOfHour(_hq_shift_lower), arrayJoin(range(toUInt64(greatest(0, dateDiff('hour', toStartOfHour(_hq_shift_lower), toStartOfHour(_hq_shift_upper)) + if(_hq_shift_upper > toStartOfHour(_hq_shift_upper) OR _hq_shift_upper_inclusive, 1, 0)))))) AS _hq_source_period FROM _hq_shift_ranges1),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time IN (SELECT r._hq_time FROM _hq_source AS r INNER JOIN _hq_shift_keys0 AS b ON toStartOfHour(r._hq_time) = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper)))) OR (_hq_time IN (SELECT r._hq_time FROM _hq_source AS r INNER JOIN _hq_shift_keys1 AS b ON toStartOfHour(r._hq_time) = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper))))),
_hq_skeleton AS (SELECT * FROM _hq_series),
_hq_fan0 AS (SELECT r.*, b._hq_period FROM _hq_scanned AS r INNER JOIN _hq_shift_keys0 AS b ON toStartOfHour(r._hq_time) = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper))),
_hq_agg0 AS (SELECT _hq_period, toNullable(sumOrNull(_hq_v0)) AS _hq_m0 FROM _hq_fan0 GROUP BY _hq_period),
_hq_fan1 AS (SELECT r.*, b._hq_period FROM _hq_scanned AS r INNER JOIN _hq_shift_keys1 AS b ON toStartOfHour(r._hq_time) = b._hq_source_period WHERE (r._hq_time > b._hq_shift_lower OR (b._hq_shift_lower_inclusive AND r._hq_time = b._hq_shift_lower)) AND (r._hq_time < b._hq_shift_upper OR (b._hq_shift_upper_inclusive AND r._hq_time = b._hq_shift_upper))),
_hq_agg1 AS (SELECT _hq_period, toNullable(sumOrNull(_hq_v0)) AS _hq_m1 FROM _hq_fan1 GROUP BY _hq_period),
_hq_values AS (SELECT s._hq_period AS period, m0._hq_m0 AS `priorHour`, m1._hq_m1 AS `priorMonth` FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period),
_hq_result AS (SELECT `period`, `priorHour`, `priorMonth` FROM _hq_values UNION ALL SELECT NULL AS `period`, NULL AS `priorHour`, NULL AS `priorMonth` FROM _hq_bounds WHERE 0 + throwIf(position(toTypeName(tupleElement((SELECT _hq_row FROM _hq_raw LIMIT 0), 1)), 'Date') > 0 AND position(toTypeName(tupleElement((SELECT _hq_row FROM _hq_raw LIMIT 0), 1)), 'DateTime') = 0, 'Sub-day time measures require a time-of-day column; Date and Date32 are not supported.') + 0 + 0 + 0 + throwIf(_hq_lower > _hq_upper, 'Window measure time range must be non-empty and ordered.') + 0 + (SELECT throwIf(countIf((toHour(_hq_period) != toHour(subtractMonths(_hq_period, 1)) OR toMinute(_hq_period) != toMinute(subtractMonths(_hq_period, 1)) OR toSecond(_hq_period) != toSecond(subtractMonths(_hq_period, 1))) OR (toHour(greatest(_hq_period, _hq_lower)) != toHour(subtractMonths(greatest(_hq_period, _hq_lower), 1)) OR toMinute(greatest(_hq_period, _hq_lower)) != toMinute(subtractMonths(greatest(_hq_period, _hq_lower), 1)) OR toSecond(greatest(_hq_period, _hq_lower)) != toSecond(subtractMonths(greatest(_hq_period, _hq_lower), 1))) OR (least(addHours(_hq_period, 1), _hq_upper) != addHours(_hq_period, 1) AND (toHour(least(addHours(_hq_period, 1), _hq_upper)) != toHour(subtractMonths(least(addHours(_hq_period, 1), _hq_upper), 1)) OR toMinute(least(addHours(_hq_period, 1), _hq_upper)) != toMinute(subtractMonths(least(addHours(_hq_period, 1), _hq_upper), 1)) OR toSecond(least(addHours(_hq_period, 1), _hq_upper)) != toSecond(subtractMonths(least(addHours(_hq_period, 1), _hq_upper), 1))))) > 0, 'Calendar shift lands on a nonexistent local time; use a UTC query timezone.') FROM _hq_series CROSS JOIN _hq_bounds) = 1) SELECT `period`, `priorHour`, `priorMonth` FROM _hq_result ORDER BY `period` ASC

